# ruff: noqa: E501
from uuid import UUID

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

from newsintel.api.dependencies import AnalystAuth
from newsintel.api.ui import COMMON_JS, render_app_page

router = APIRouter(tags=["analyst-workspace-dashboard"])


@router.get("/investigations", response_class=HTMLResponse)
async def investigations_dashboard(auth: AnalystAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "analyst")
    body = r"""
<section class="page-head">
  <div><div class="eyebrow">Saved research</div><h1>Investigations</h1><p class="lead">Keep articles, events, notes and saved searches together. Share a case with approved teammates and follow updates without changing the underlying evidence.</p></div>
  <div class="toolbar"><button id="newInvestigationBtn" type="button">New investigation</button><button id="newWatchlistBtn" class="secondary" type="button">New watchlist</button></div>
</section>
<section class="grid five metrics-5">
  <div class="metric"><div class="label">Active investigations</div><div class="value" id="mInvestigations">—</div></div>
  <div class="metric"><div class="label">Shared with me</div><div class="value" id="mShared">—</div></div>
  <div class="metric"><div class="label">Watchlists</div><div class="value" id="mWatchlists">—</div></div>
  <div class="metric"><div class="label">Scheduled searches</div><div class="value" id="mMonitors">—</div></div>
  <div class="metric"><div class="label">Attention</div><div class="value" id="mAlerts">—</div><div class="hint">Unacknowledged changes</div></div>
</section>
<section id="incomingPanel" class="panel" style="margin-top:18px" hidden>
  <div class="section-head"><div><h2>Add tracked material</h2><div class="muted small" id="incomingDescription">Choose where this material belongs.</div></div><button id="dismissIncoming" class="ghost" type="button">Dismiss</button></div>
  <div class="grid two"><label>Investigation<select id="incomingInvestigation"><option value="">Choose editable investigation</option></select></label><label>Watchlist<select id="incomingWatchlist"><option value="">Choose watchlist</option></select></label></div>
  <label style="display:block;margin-top:12px">Optional note<textarea id="incomingNote" placeholder="Why is this material relevant?"></textarea></label>
  <div class="toolbar" style="margin-top:12px"><button id="addToInvestigation" type="button">Add to investigation</button><button id="addToWatchlist" class="secondary" type="button">Add to watchlist</button></div>
</section>
<section class="workspace-layout" style="margin-top:18px">
  <div class="stack">
    <section class="panel"><div class="section-head"><div><h2>Investigations</h2><div class="muted small">Owned and shared cases. Access badges show what you can change.</div></div></div><div id="investigationList" class="stack"><div class="skeleton" style="height:180px"></div></div></section>
    <section class="panel"><div class="section-head"><div><h2>Saved searches</h2><div class="muted small">Your repeatable corpus queries. Enable monitoring to create change alerts on a durable schedule.</div></div></div><div id="savedSearchList" class="stack"></div></section>
  </div>
  <div class="stack">
    <section class="panel"><div class="section-head"><div><h2>Attention required</h2><div class="muted small">Watchlist changes plus scheduled-search result-window changes.</div></div><button id="refreshWorkspace" class="secondary" type="button">Refresh</button></div><div id="alertList" class="stack"><div class="skeleton" style="height:160px"></div></div></section>
    <section class="panel"><div class="section-head"><div><h2>Watchlists</h2><div class="muted small">Monitor selected events, articles or claims.</div></div></div><div id="watchlistList" class="stack"></div></section>
  </div>
</section>
<dialog id="investigationDialog"><form method="dialog" class="dialog-card"><div class="section-head"><h2>New investigation</h2><button class="ghost" value="cancel" aria-label="Close">Close</button></div><label>Title<input id="investigationTitle" maxlength="240" placeholder="Coal regulation amendment" /></label><label>Description<textarea id="investigationDescription" maxlength="8000" placeholder="What question are you investigating?"></textarea></label><label>Priority<select id="investigationPriority"><option value="normal">Normal</option><option value="high">High</option><option value="critical">Critical</option><option value="low">Low</option></select></label><div class="toolbar" style="margin-top:14px"><button id="createInvestigation" type="button">Create investigation</button></div></form></dialog>
<dialog id="watchlistDialog"><form method="dialog" class="dialog-card"><div class="section-head"><h2>New watchlist</h2><button class="ghost" value="cancel" aria-label="Close">Close</button></div><label>Name<input id="watchlistName" maxlength="200" placeholder="Coal policy watch" /></label><label>Description<textarea id="watchlistDescription" maxlength="4000" placeholder="What should this watchlist monitor?"></textarea></label><div class="toolbar" style="margin-top:14px"><button id="createWatchlist" type="button">Create watchlist</button></div></form></dialog>
<dialog id="monitorDialog"><form method="dialog" class="dialog-card"><div class="section-head"><div><h2>Scheduled search monitoring</h2><div id="monitorSearchName" class="muted small"></div></div><button class="ghost" value="cancel" aria-label="Close">Close</button></div><label>Monitoring<select id="monitorEnabled"><option value="true">Enabled</option><option value="false">Disabled</option></select></label><label>Cadence<select id="monitorCadence"><option value="60">Every hour</option><option value="180">Every 3 hours</option><option value="360">Every 6 hours</option><option value="720">Every 12 hours</option><option value="1440">Daily</option><option value="10080">Weekly</option></select></label><div class="notice"><b>Change semantics</b><div class="small">The first run establishes a baseline. Later alerts report results that enter the monitored top-result window; they are not truth judgments or exhaustive web-change detection.</div></div><div><b>Recent evaluations</b><div id="monitorRuns" class="stack" style="margin-top:8px"><div class="muted small">No evaluations loaded.</div></div></div><div class="toolbar"><button id="saveMonitor" type="button">Save monitoring</button></div></form></dialog>
"""
    extra_css = r"""
.workspace-layout{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(330px,.75fr);gap:18px}.workspace-card{padding:15px;border:1px solid var(--line);border-radius:13px;background:var(--surface-2)}.workspace-card h3{margin:5px 0;font-size:17px}.alert-card{padding:14px;border-left:4px solid var(--line-strong);border-radius:10px;background:var(--surface-2)}.alert-card.high,.alert-card.critical{border-left-color:var(--bad)}.alert-card.medium{border-left-color:#d69a00}.dialog-card{min-width:min(560px,calc(100vw - 36px));display:grid;gap:12px}dialog{border:1px solid var(--line);border-radius:16px;background:var(--surface);color:var(--text);box-shadow:var(--shadow);padding:20px}dialog::backdrop{background:rgba(10,18,35,.5)}.metrics-5{grid-template-columns:repeat(5,minmax(0,1fr))}.access-owner{font-weight:800}.monitor-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--good);margin-right:5px}@media(max-width:1050px){.metrics-5{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:900px){.workspace-layout{grid-template-columns:1fr}}@media(max-width:650px){.metrics-5{grid-template-columns:repeat(2,minmax(0,1fr))}}
"""
    scripts = f"""<script>{COMMON_JS}
let workspace={{investigations:[],watchlists:[],saved_searches:[],alerts:[],counts:{{}}}};let monitorSearch=null;const params=new URLSearchParams(location.search);const incomingType=params.get('add_type');const incomingId=params.get('add_id');
function priorityKind(v){{return v==='critical'?'bad':v==='high'?'warn':'neutral'}}
function accessKind(v){{return v==='owner'?'good':v==='editor'?'info':'neutral'}}
function targetHref(type,id){{if(type==='event')return `/events/${{id}}/intelligence`;if(type==='article')return `/articles/${{id}}/intelligence`;if(type==='claim')return `/claims/${{id}}/investigation`;return '#'}}
function cadenceLabel(minutes){{if(minutes===60)return 'hourly';if(minutes===1440)return 'daily';if(minutes===10080)return 'weekly';return `every ${{Math.round(minutes/60)}}h`}}
function savedSearchHref(x){{const p=new URLSearchParams({{q:x.query}});const f=x.filters||{{}};if(f.result_type&&f.result_type!=='all')p.set('type',f.result_type);for(const key of ['language','publisher','lifecycle_status','from_date','to_date']){{if(f[key])p.set(key,String(f[key]));}}return `/search?${{p.toString()}}`}}
async function loadMonitorRuns(id){{const box=document.getElementById('monitorRuns');if(!box)return;box.innerHTML='<div class="muted small">Loading evaluation history…</div>';try{{const runs=await niApi(`/api/v1/saved-searches/${{id}}/monitor/runs?limit=8`);box.innerHTML=runs.length?runs.map(r=>`<article class="activity-card"><div class="section-head" style="margin:0"><b>${{niEsc(niTitle(r.status))}}</b><span class="muted small">${{niRelative(r.started_at)}}</span></div><div class="muted small" style="margin-top:4px">${{r.result_count}} results · ${{r.new_result_count}} new in monitored window</div>${{r.error?`<div class="error-box small" style="margin-top:6px">${{niEsc(r.error)}}</div>`:''}}</article>`).join(''):'<div class="muted small">No completed evaluations yet. The first run establishes the baseline.</div>'}}catch(e){{box.innerHTML=`<div class="error-box small">${{niEsc(e.message)}}</div>`}}}}

function renderWorkspace(){{const c=workspace.counts||{{}};document.getElementById('mInvestigations').textContent=c.active_investigations||0;document.getElementById('mShared').textContent=(workspace.investigations||[]).filter(x=>x.access_role!=='owner').length;document.getElementById('mWatchlists').textContent=c.watchlists||0;document.getElementById('mMonitors').textContent=c.scheduled_monitors||0;document.getElementById('mAlerts').textContent=c.unacknowledged_alerts||0;renderInvestigations();renderWatchlists();renderSearches();renderAlerts();renderIncoming()}}
function renderInvestigations(){{const box=document.getElementById('investigationList');const rows=workspace.investigations||[];box.innerHTML=rows.length?rows.map(x=>`<article class="workspace-card"><div class="pill-row">${{niPill(niTitle(x.status),x.status==='active'?'good':'neutral')}}${{niPill(niTitle(x.priority),priorityKind(x.priority))}}${{niPill(niTitle(x.access_role),accessKind(x.access_role))}}</div><h3><a href="/investigations/${{x.id}}">${{niEsc(x.title)}}</a></h3>${{x.description?`<div class="muted small">${{niEsc(x.description)}}</div>`:''}}<div class="muted small" style="margin-top:8px">${{x.item_count}} tracked · ${{x.note_count}} notes · ${{x.member_count}} collaborators · updated ${{niRelative(x.updated_at)}}</div>${{x.access_role!=='owner'?`<div class="muted small" style="margin-top:5px">Shared by ${{niEsc(x.owner_display_name||'investigation owner')}}</div>`:''}}</article>`).join(''):'<div class="empty">No investigations yet. Create one for a research question you expect to revisit.</div>';fillIncomingSelects()}}
function renderWatchlists(){{const box=document.getElementById('watchlistList');const rows=workspace.watchlists||[];box.innerHTML=rows.length?rows.map(x=>`<article class="workspace-card"><b><a href="/watchlists/${{x.id}}">${{niEsc(x.name)}}</a></b><div class="muted small">${{x.item_count}} watched items${{x.description?` · ${{niEsc(x.description)}}`:''}}</div></article>`).join(''):'<div class="empty">No watchlists yet.</div>';fillIncomingSelects()}}
function renderSearches(){{const box=document.getElementById('savedSearchList');const rows=workspace.saved_searches||[];box.innerHTML=rows.length?rows.map(x=>`<article class="workspace-card"><div class="section-head" style="margin:0"><div><b>${{niEsc(x.name)}}</b><div class="muted small">${{niEsc(x.query)}}</div></div><button class="ghost" type="button" onclick="deleteSearch('${{x.id}}')">Remove</button></div><div class="pill-row" style="margin-top:8px">${{x.monitor?.enabled?`<span class="pill good"><span class="monitor-dot"></span>Monitoring ${{cadenceLabel(x.monitor.cadence_minutes)}}</span>`:niPill('Manual only','neutral')}}</div><div class="muted small" style="margin-top:6px">${{x.monitor?.last_success_at?`Last monitored ${{niRelative(x.monitor.last_success_at)}} · next ${{niRelative(x.monitor.next_run_at)}}`:x.monitor?.enabled?'Baseline pending':'No scheduled evaluation'}}</div><div class="toolbar" style="margin-top:8px"><a class="button secondary" href="${{savedSearchHref(x)}}">Run search</a><button class="ghost" type="button" onclick="openMonitor('${{x.id}}')">${{x.monitor?.enabled?'Monitoring settings':'Schedule'}}</button>${{x.investigation_id?`<a class="small" href="/investigations/${{x.investigation_id}}">Open investigation</a>`:''}}</div></article>`).join(''):'<div class="empty">No saved searches. Search the corpus and save useful queries.</div>'}}
function renderAlerts(){{const box=document.getElementById('alertList');const rows=workspace.alerts||[];box.innerHTML=rows.length?rows.map(x=>`<article class="alert-card ${{niEsc(x.severity)}}"><div class="pill-row">${{niPill(niTitle(x.alert_type),x.severity==='critical'||x.severity==='high'?'bad':x.severity==='medium'?'warn':'neutral')}}</div><b style="display:block;margin-top:7px">${{niEsc(x.title)}}</b><div class="muted small" style="margin-top:4px">${{niEsc(x.detail)}}</div><div class="muted small" style="margin-top:5px">${{niRelative(x.occurred_at)}}</div><div class="toolbar" style="margin-top:9px"><a class="button secondary" href="${{niEsc(x.link)}}">Inspect</a><button class="ghost" type="button" onclick="ackAlert('${{encodeURIComponent(x.alert_key)}}')">Acknowledge</button></div></article>`).join(''):'<div class="empty">No unacknowledged monitored changes.</div>'}}
function fillIncomingSelects(){{const i=document.getElementById('incomingInvestigation'),w=document.getElementById('incomingWatchlist');if(!i||!w)return;const editable=(workspace.investigations||[]).filter(x=>x.status==='active'&&x.access_role!=='reader');i.innerHTML='<option value="">Choose editable investigation</option>'+editable.map(x=>`<option value="${{x.id}}">${{niEsc(x.title)}} (${{niTitle(x.access_role)}})</option>`).join('');w.innerHTML='<option value="">Choose watchlist</option>'+(workspace.watchlists||[]).map(x=>`<option value="${{x.id}}">${{niEsc(x.name)}}</option>`).join('')}}
function renderIncoming(){{const panel=document.getElementById('incomingPanel');if(!incomingType||!incomingId||!['event','article','claim'].includes(incomingType)){{panel.hidden=true;return}}panel.hidden=false;document.getElementById('incomingDescription').textContent=`Add this ${{incomingType}} to an editable investigation and/or a private watchlist.`;fillIncomingSelects()}}
async function loadWorkspace(){{try{{workspace=await niApi('/api/v1/workspace/overview');renderWorkspace()}}catch(e){{document.getElementById('investigationList').innerHTML=`<div class="error-box">${{niEsc(e.message)}}</div>`}}}}
async function createInvestigation(){{const title=document.getElementById('investigationTitle').value.trim();if(title.length<2){{niToast('Enter an investigation title','bad');return}}try{{const row=await niApi('/api/v1/investigations',{{method:'POST',body:JSON.stringify({{title,description:document.getElementById('investigationDescription').value.trim()||null,priority:document.getElementById('investigationPriority').value}})}});document.getElementById('investigationDialog').close();location.href=`/investigations/${{row.id}}`}}catch(e){{niToast(e.message,'bad')}}}}
async function createWatchlist(){{const name=document.getElementById('watchlistName').value.trim();if(name.length<2){{niToast('Enter a watchlist name','bad');return}}try{{await niApi('/api/v1/watchlists',{{method:'POST',body:JSON.stringify({{name,description:document.getElementById('watchlistDescription').value.trim()||null}})}});document.getElementById('watchlistDialog').close();niToast('Watchlist created','good');await loadWorkspace()}}catch(e){{niToast(e.message,'bad')}}}}
async function deleteSearch(id){{try{{await niApi(`/api/v1/saved-searches/${{id}}`,{{method:'DELETE'}});niToast('Saved search removed','good');await loadWorkspace()}}catch(e){{niToast(e.message,'bad')}}}}
function openMonitor(id){{monitorSearch=(workspace.saved_searches||[]).find(x=>x.id===id);if(!monitorSearch)return;document.getElementById('monitorSearchName').textContent=monitorSearch.name;document.getElementById('monitorEnabled').value=monitorSearch.monitor?.enabled?'true':'false';document.getElementById('monitorCadence').value=String(monitorSearch.monitor?.cadence_minutes||360);document.getElementById('monitorDialog').showModal();loadMonitorRuns(id)}}
async function saveMonitor(){{if(!monitorSearch)return;const enabled=document.getElementById('monitorEnabled').value==='true',cadence_minutes=Number(document.getElementById('monitorCadence').value);try{{await niApi(`/api/v1/saved-searches/${{monitorSearch.id}}/monitor`,{{method:'PUT',body:JSON.stringify({{enabled,cadence_minutes}})}});document.getElementById('monitorDialog').close();niToast(enabled?'Scheduled monitoring enabled':'Scheduled monitoring disabled','good');await loadWorkspace()}}catch(e){{niToast(e.message,'bad')}}}}
async function ackAlert(key){{try{{await niApi(`/api/v1/workspace/alerts/${{key}}/acknowledge`,{{method:'POST'}});await loadWorkspace()}}catch(e){{niToast(e.message,'bad')}}}}
async function addIncoming(kind){{if(!incomingType||!incomingId)return;const id=kind==='investigation'?document.getElementById('incomingInvestigation').value:document.getElementById('incomingWatchlist').value;if(!id){{niToast(`Choose a ${{kind}} first`,'bad');return}}const path=kind==='investigation'?`/api/v1/investigations/${{id}}/items`:`/api/v1/watchlists/${{id}}/items`;try{{await niApi(path,{{method:'POST',body:JSON.stringify({{item_type:incomingType,item_id:incomingId,note:document.getElementById('incomingNote').value.trim()||null}})}});niToast(`Added to ${{kind}}`,'good')}}catch(e){{niToast(e.message,'bad')}}}}
document.getElementById('newInvestigationBtn').addEventListener('click',()=>document.getElementById('investigationDialog').showModal());document.getElementById('newWatchlistBtn').addEventListener('click',()=>document.getElementById('watchlistDialog').showModal());document.getElementById('createInvestigation').addEventListener('click',createInvestigation);document.getElementById('createWatchlist').addEventListener('click',createWatchlist);document.getElementById('refreshWorkspace').addEventListener('click',loadWorkspace);document.getElementById('dismissIncoming').addEventListener('click',()=>{{document.getElementById('incomingPanel').hidden=true;history.replaceState(null,'','/investigations')}});document.getElementById('addToInvestigation').addEventListener('click',()=>addIncoming('investigation'));document.getElementById('addToWatchlist').addEventListener('click',()=>addIncoming('watchlist'));document.getElementById('saveMonitor').addEventListener('click',saveMonitor);loadWorkspace();
</script>"""
    return render_app_page(title="Investigations", body=body, active="investigations", role=role, scripts=scripts, extra_css=extra_css)


@router.get("/investigations/{investigation_id}", response_class=HTMLResponse)
async def investigation_detail_dashboard(investigation_id: UUID, auth: AnalystAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "analyst")
    investigation_id_text = str(investigation_id)
    body = r"""
<section class="page-head"><div><div class="eyebrow">Investigation workspace</div><h1 id="investigationTitle">Loading investigation…</h1><p id="investigationDescription" class="lead"></p><div class="pill-row" id="accessBadges" style="margin-top:8px"></div></div><div class="toolbar"><button id="shareBtn" class="secondary" type="button" hidden>Manage collaborators</button><button id="archiveBtn" class="secondary" type="button" hidden>Archive</button><a class="button secondary" id="manifestLink" target="_blank" rel="noopener">Evidence manifest</a><a class="button secondary" href="/investigations">All investigations</a></div></section>
<section class="grid five metrics-5"><div class="metric"><div class="label">Tracked material</div><div class="value" id="mItems">—</div></div><div class="metric"><div class="label">Notes</div><div class="value" id="mNotes">—</div></div><div class="metric"><div class="label">Saved searches</div><div class="value" id="mSearches">—</div></div><div class="metric"><div class="label">Collaborators</div><div class="value" id="mMembers">—</div></div><div class="metric"><div class="label">Last activity</div><div class="value small-value" id="mUpdated">—</div></div></section>
<section class="investigation-layout" style="margin-top:18px"><div class="stack"><section class="panel"><div class="section-head"><div><h2>Tracked material</h2><div class="muted small">Canonical events, articles and claims attached to this case.</div></div></div><div id="itemList" class="stack"></div></section><section class="panel"><div class="section-head"><div><h2>Analyst notes</h2><div class="muted small">Analyst-authored observations remain separate from source evidence.</div></div><span id="noteCount" class="muted small"></span></div><div id="noteComposer"><label>New investigation note<textarea id="noteBody" maxlength="20000" placeholder="Observation, hypothesis or follow-up question…"></textarea></label><div class="toolbar"><label class="inline-check"><input id="notePinned" type="checkbox" /> Pin note</label><button id="addNote" type="button">Add note</button></div></div><div id="noteReadOnly" class="notice" hidden>Reader access is view-only. Ask the investigation owner for editor access to add research notes.</div><div id="noteList" class="stack" style="margin-top:14px"></div></section><section class="panel"><div class="section-head"><div><h2>Saved searches</h2><div class="muted small">Shared case context; each saved search remains owned by the analyst who created it.</div></div></div><div id="searchList" class="stack"></div></section></div><div class="stack"><section class="panel"><div class="section-head"><div><h2>Collaborators</h2><div class="muted small">Owner has full control. Editors can change case contents; readers are view-only.</div></div></div><div id="memberList" class="stack"></div></section><section class="panel"><div class="section-head"><div><h2>Activity</h2><div class="muted small">Auditable case-level research and collaboration history.</div></div></div><div id="activityList" class="stack"></div></section></div></section>
<dialog id="memberDialog"><form method="dialog" class="dialog-card"><div class="section-head"><div><h2>Add collaborator</h2><div class="muted small">Enter the exact verified email of an approved analyst account.</div></div><button class="ghost" value="cancel">Close</button></div><label>Verified email<input id="memberEmail" type="email" maxlength="320" placeholder="analyst@example.com" /></label><label>Case access<select id="memberRole"><option value="reader">Reader — view only</option><option value="editor">Editor — add/remove research material and notes</option></select></label><div class="notice"><b>Sharing boundary</b><div class="small">Sharing this investigation does not grant platform permissions the account does not already have.</div></div><div class="toolbar"><button id="addMember" type="button">Add collaborator</button></div></form></dialog>
<dialog id="monitorDialog"><form method="dialog" class="dialog-card"><div class="section-head"><div><h2>Scheduled search monitoring</h2><div id="monitorSearchName" class="muted small"></div></div><button class="ghost" value="cancel">Close</button></div><label>Monitoring<select id="monitorEnabled"><option value="true">Enabled</option><option value="false">Disabled</option></select></label><label>Cadence<select id="monitorCadence"><option value="60">Every hour</option><option value="180">Every 3 hours</option><option value="360">Every 6 hours</option><option value="720">Every 12 hours</option><option value="1440">Daily</option><option value="10080">Weekly</option></select></label><div><b>Recent evaluations</b><div id="monitorRuns" class="stack" style="margin-top:8px"><div class="muted small">No evaluations loaded.</div></div></div><div class="toolbar"><button id="saveMonitor" type="button">Save monitoring</button></div></form></dialog>
"""
    extra_css = r"""
.investigation-layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(320px,.8fr);gap:18px}.tracked-item,.note-card,.member-card,.activity-card{padding:13px;border:1px solid var(--line);border-radius:12px;background:var(--surface-2)}.note-card.pinned{border-left:4px solid #d69a00}.activity-card{padding:11px}.small-value{font-size:15px!important;line-height:1.3}.dialog-card{min-width:min(560px,calc(100vw - 36px));display:grid;gap:12px}dialog{border:1px solid var(--line);border-radius:16px;background:var(--surface);color:var(--text);box-shadow:var(--shadow);padding:20px}dialog::backdrop{background:rgba(10,18,35,.5)}.metrics-5{grid-template-columns:repeat(5,minmax(0,1fr))}@media(max-width:1050px){.metrics-5{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:900px){.investigation-layout{grid-template-columns:1fr}}@media(max-width:650px){.metrics-5{grid-template-columns:repeat(2,minmax(0,1fr))}}
"""
    scripts = f"""<script>{COMMON_JS}
const investigationId={investigation_id_text!r};let investigation=null;let monitorSearch=null;
function targetHref(x){{if(x.item_type==='event')return `/events/${{x.item_id}}/intelligence`;if(x.item_type==='article')return `/articles/${{x.item_id}}/intelligence`;if(x.item_type==='claim')return `/claims/${{x.item_id}}/investigation`;return '#'}}
function cadenceLabel(minutes){{if(minutes===60)return 'hourly';if(minutes===1440)return 'daily';if(minutes===10080)return 'weekly';return `every ${{Math.round(minutes/60)}}h`}}
function savedSearchHref(x){{const p=new URLSearchParams({{q:x.query}});const f=x.filters||{{}};if(f.result_type&&f.result_type!=='all')p.set('type',f.result_type);for(const key of ['language','publisher','lifecycle_status','from_date','to_date']){{if(f[key])p.set(key,String(f[key]));}}return `/search?${{p.toString()}}`}}
async function loadMonitorRuns(id){{const box=document.getElementById('monitorRuns');if(!box)return;box.innerHTML='<div class="muted small">Loading evaluation history…</div>';try{{const runs=await niApi(`/api/v1/saved-searches/${{id}}/monitor/runs?limit=8`);box.innerHTML=runs.length?runs.map(r=>`<article class="activity-card"><div class="section-head" style="margin:0"><b>${{niEsc(niTitle(r.status))}}</b><span class="muted small">${{niRelative(r.started_at)}}</span></div><div class="muted small" style="margin-top:4px">${{r.result_count}} results · ${{r.new_result_count}} new in monitored window</div>${{r.error?`<div class="error-box small" style="margin-top:6px">${{niEsc(r.error)}}</div>`:''}}</article>`).join(''):'<div class="muted small">No completed evaluations yet. The first run establishes the baseline.</div>'}}catch(e){{box.innerHTML=`<div class="error-box small">${{niEsc(e.message)}}</div>`}}}}

function canDeleteNote(n){{return investigation.access_role==='owner'||n.author_user_id===investigation.current_user_id}}
function render(){{document.getElementById('investigationTitle').textContent=investigation.title;document.getElementById('investigationDescription').textContent=investigation.description||'No description.';document.getElementById('accessBadges').innerHTML=niPill(niTitle(investigation.access_role),investigation.access_role==='owner'?'good':investigation.access_role==='editor'?'info':'neutral')+niPill(niTitle(investigation.priority),investigation.priority==='critical'?'bad':investigation.priority==='high'?'warn':'neutral')+niPill(niTitle(investigation.status),investigation.status==='active'?'good':'neutral');document.getElementById('mItems').textContent=investigation.items.length;document.getElementById('mNotes').textContent=investigation.notes.length;document.getElementById('mSearches').textContent=investigation.saved_searches.length;document.getElementById('mMembers').textContent=investigation.members.length;document.getElementById('mUpdated').textContent=niRelative(investigation.updated_at);document.getElementById('manifestLink').href=`/api/v1/investigations/${{investigationId}}/manifest`;document.getElementById('archiveBtn').hidden=!investigation.can_manage_members;document.getElementById('shareBtn').hidden=!investigation.can_manage_members;document.getElementById('archiveBtn').textContent=investigation.status==='active'?'Archive':'Reopen';document.getElementById('noteComposer').hidden=!investigation.can_edit;document.getElementById('noteReadOnly').hidden=investigation.can_edit;renderItems();renderNotes();renderSearches();renderMembers();renderActivity()}}
function renderItems(){{const box=document.getElementById('itemList');box.innerHTML=investigation.items.length?investigation.items.map(x=>`<article class="tracked-item"><div class="section-head" style="margin:0"><div><div class="pill-row">${{niPill(niTitle(x.item_type),'neutral')}}</div><b style="display:block;margin-top:6px"><a href="${{targetHref(x)}}">${{niEsc(x.label)}}</a></b>${{x.note?`<div class="muted small" style="margin-top:5px">${{niEsc(x.note)}}</div>`:''}}<div class="muted small" style="margin-top:5px">Added ${{niDate(x.added_at)}}</div></div>${{investigation.can_edit?`<button class="ghost" type="button" onclick="removeItem('${{x.id}}')">Remove</button>`:''}}</div></article>`).join(''):'<div class="empty">No tracked material yet. Open an event, article or claim and choose Add to workspace.</div>'}}
function renderNotes(){{const box=document.getElementById('noteList');document.getElementById('noteCount').textContent=`${{investigation.notes.length}} notes`;box.innerHTML=investigation.notes.length?investigation.notes.map(n=>`<article class="note-card ${{n.pinned?'pinned':''}}"><div class="pill-row">${{n.pinned?niPill('Pinned','warn'):''}}${{niPill(niTitle(n.target_type),'neutral')}}</div><div class="prose" style="margin-top:7px">${{niEsc(n.body)}}</div><div class="section-head" style="margin:8px 0 0"><span class="muted small">${{niEsc(n.author_display_name||'Analyst')}} · ${{niDate(n.created_at)}}</span>${{canDeleteNote(n)?`<button class="ghost" type="button" onclick="removeNote('${{n.id}}')">Delete</button>`:''}}</div></article>`).join(''):'<div class="empty">No analyst notes yet.</div>'}}
function renderSearches(){{const box=document.getElementById('searchList');box.innerHTML=investigation.saved_searches.length?investigation.saved_searches.map(x=>`<article class="tracked-item"><div class="section-head" style="margin:0"><div><b>${{niEsc(x.name)}}</b><div class="muted small">${{niEsc(x.query)}} · saved by ${{niEsc(x.owner_display_name||'analyst')}}</div></div>${{x.owner_user_id===investigation.current_user_id?`<button class="ghost" type="button" onclick="removeSearch('${{x.id}}')">Remove</button>`:''}}</div><div class="pill-row" style="margin-top:8px">${{x.monitor?.enabled?niPill(`Monitoring ${{cadenceLabel(x.monitor.cadence_minutes)}}`,'good'):niPill('Manual only','neutral')}}</div><div class="toolbar" style="margin-top:8px"><a class="button secondary" href="${{savedSearchHref(x)}}">Run search</a>${{x.owner_user_id===investigation.current_user_id?`<button class="ghost" type="button" onclick="openMonitor('${{x.id}}')">${{x.monitor?.enabled?'Monitoring settings':'Schedule'}}</button>`:''}}</div></article>`).join(''):'<div class="empty">No saved searches attached to this investigation.</div>'}}
function renderMembers(){{const box=document.getElementById('memberList');const owner=`<article class="member-card"><div class="pill-row">${{niPill('Owner','good')}}</div><b>${{niEsc(investigation.owner_display_name||'Investigation owner')}}</b><div class="muted small">Full case control and sharing authority</div></article>`;const members=investigation.members.map(m=>`<article class="member-card"><div class="section-head" style="margin:0"><div><div class="pill-row">${{niPill(niTitle(m.access_role),m.access_role==='editor'?'info':'neutral')}}</div><b>${{niEsc(m.display_name||m.verified_email||'Collaborator')}}</b><div class="muted small">${{niEsc(m.verified_email||'')}}</div></div>${{investigation.can_manage_members?`<div class="toolbar"><select aria-label="Collaborator access" onchange="changeMemberRole('${{m.id}}',this.value)"><option value="reader" ${{m.access_role==='reader'?'selected':''}}>Reader</option><option value="editor" ${{m.access_role==='editor'?'selected':''}}>Editor</option></select><button class="ghost" type="button" onclick="removeMember('${{m.id}}')">Remove</button></div>`:''}}</div></article>`).join('');box.innerHTML=owner+members}}
function renderActivity(){{const box=document.getElementById('activityList');box.innerHTML=investigation.activity.length?investigation.activity.map(a=>`<article class="activity-card"><div><b>${{niEsc(a.summary)}}</b></div><div class="muted small" style="margin-top:4px">${{niEsc(a.actor_display_name||'System')}} · ${{niDate(a.created_at)}} · ${{niTitle(a.action)}}</div></article>`).join(''):'<div class="empty">No recorded case activity yet.</div>'}}
async function load(){{try{{investigation=await niApi(`/api/v1/investigations/${{investigationId}}`);render()}}catch(e){{document.getElementById('investigationTitle').textContent='Investigation unavailable';document.getElementById('investigationDescription').textContent=e.message}}}}
async function addNote(){{const body=document.getElementById('noteBody').value.trim();if(!body){{niToast('Write a note first','bad');return}}try{{await niApi(`/api/v1/investigations/${{investigationId}}/notes`,{{method:'POST',body:JSON.stringify({{body,pinned:document.getElementById('notePinned').checked,target_type:'investigation',target_id:investigationId}})}});document.getElementById('noteBody').value='';document.getElementById('notePinned').checked=false;niToast('Note added','good');await load()}}catch(e){{niToast(e.message,'bad')}}}}
async function removeItem(id){{try{{await niApi(`/api/v1/investigations/${{investigationId}}/items/${{id}}`,{{method:'DELETE'}});await load()}}catch(e){{niToast(e.message,'bad')}}}}
async function removeNote(id){{try{{await niApi(`/api/v1/notes/${{id}}`,{{method:'DELETE'}});await load()}}catch(e){{niToast(e.message,'bad')}}}}
async function removeSearch(id){{try{{await niApi(`/api/v1/saved-searches/${{id}}`,{{method:'DELETE'}});await load()}}catch(e){{niToast(e.message,'bad')}}}}
async function toggleArchive(){{const status=investigation.status==='active'?'archived':'active';try{{investigation=await niApi(`/api/v1/investigations/${{investigationId}}`,{{method:'PATCH',body:JSON.stringify({{status}})}});niToast(status==='archived'?'Investigation archived':'Investigation reopened','good');render()}}catch(e){{niToast(e.message,'bad')}}}}
async function addMember(){{const email=document.getElementById('memberEmail').value.trim(),access_role=document.getElementById('memberRole').value;if(!email){{niToast('Enter the collaborator verified email','bad');return}}try{{await niApi(`/api/v1/investigations/${{investigationId}}/members`,{{method:'POST',body:JSON.stringify({{email,access_role}})}});document.getElementById('memberDialog').close();document.getElementById('memberEmail').value='';niToast('Collaborator added','good');await load()}}catch(e){{niToast(e.message,'bad')}}}}
async function changeMemberRole(memberId,access_role){{try{{await niApi(`/api/v1/investigations/${{investigationId}}/members/${{memberId}}`,{{method:'PATCH',body:JSON.stringify({{access_role}})}});niToast('Collaborator access updated','good');await load()}}catch(e){{niToast(e.message,'bad');await load()}}}}
async function removeMember(memberId){{try{{await niApi(`/api/v1/investigations/${{investigationId}}/members/${{memberId}}`,{{method:'DELETE'}});niToast('Collaborator removed','good');await load()}}catch(e){{niToast(e.message,'bad')}}}}
function openMonitor(id){{monitorSearch=investigation.saved_searches.find(x=>x.id===id);if(!monitorSearch)return;document.getElementById('monitorSearchName').textContent=monitorSearch.name;document.getElementById('monitorEnabled').value=monitorSearch.monitor?.enabled?'true':'false';document.getElementById('monitorCadence').value=String(monitorSearch.monitor?.cadence_minutes||360);document.getElementById('monitorDialog').showModal();loadMonitorRuns(id)}}
async function saveMonitor(){{if(!monitorSearch)return;try{{await niApi(`/api/v1/saved-searches/${{monitorSearch.id}}/monitor`,{{method:'PUT',body:JSON.stringify({{enabled:document.getElementById('monitorEnabled').value==='true',cadence_minutes:Number(document.getElementById('monitorCadence').value)}})}});document.getElementById('monitorDialog').close();niToast('Monitoring settings saved','good');await load()}}catch(e){{niToast(e.message,'bad')}}}}
document.getElementById('addNote').addEventListener('click',addNote);document.getElementById('archiveBtn').addEventListener('click',toggleArchive);document.getElementById('shareBtn').addEventListener('click',()=>document.getElementById('memberDialog').showModal());document.getElementById('addMember').addEventListener('click',addMember);document.getElementById('saveMonitor').addEventListener('click',saveMonitor);load();
</script>"""
    return render_app_page(title="Investigation", body=body, active="investigations", role=role, scripts=scripts, extra_css=extra_css)


@router.get("/watchlists/{watchlist_id}", response_class=HTMLResponse)
async def watchlist_detail_dashboard(watchlist_id: UUID, auth: AnalystAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "analyst")
    watchlist_id_text = str(watchlist_id)
    body = r"""
<section class="page-head"><div><div class="eyebrow">Monitoring workspace</div><h1 id="watchlistTitle">Loading watchlist…</h1><p id="watchlistDescription" class="lead"></p></div><div class="toolbar"><button id="deleteWatchlistBtn" class="danger" type="button">Delete watchlist</button><a class="button secondary" href="/investigations">Investigations</a></div></section>
<section class="grid three"><div class="metric"><div class="label">Watched items</div><div class="value" id="mItems">—</div></div><div class="metric"><div class="label">Unacknowledged changes</div><div class="value" id="mAlerts">—</div></div><div class="metric"><div class="label">Updated</div><div class="value" id="mUpdated" style="font-size:16px">—</div></div></section>
<section class="grid two" style="margin-top:18px"><div class="panel"><div class="section-head"><div><h2>Watched material</h2><div class="muted small">Items on this list are the only material used to derive its alerts.</div></div></div><div id="watchItems" class="stack"></div></div><div class="panel"><div class="section-head"><div><h2>Recent changes</h2><div class="muted small">Corrections, review flags and material event changes derived from this list.</div></div></div><div id="watchAlerts" class="stack"></div></div></section>
<dialog id="deleteWatchlistDialog"><form method="dialog" class="dialog-card"><h2>Delete watchlist?</h2><p class="muted">This removes the monitoring list and its memberships. It does not delete any event, article, claim, correction, evidence, or verification record.</p><div class="toolbar"><button class="danger" id="confirmDeleteWatchlist" type="button">Delete watchlist</button><button class="secondary" value="cancel">Cancel</button></div></form></dialog>
"""
    scripts = f"""<script>{COMMON_JS}
const watchlistId={watchlist_id_text!r};let watchlist=null;let alerts=[];
function targetHref(x){{if(x.item_type==='event')return `/events/${{x.item_id}}/intelligence`;if(x.item_type==='article')return `/articles/${{x.item_id}}/intelligence`;if(x.item_type==='claim')return `/claims/${{x.item_id}}/investigation`;return '#'}}
function render(){{document.getElementById('watchlistTitle').textContent=watchlist.name;document.getElementById('watchlistDescription').textContent=watchlist.description||'No description.';document.getElementById('mItems').textContent=watchlist.items.length;const mine=alerts.filter(a=>(a.watchlist_ids||[]).includes(watchlistId));document.getElementById('mAlerts').textContent=mine.length;document.getElementById('mUpdated').textContent=niRelative(watchlist.updated_at);document.getElementById('watchItems').innerHTML=watchlist.items.length?watchlist.items.map(x=>`<article class="evidence-item"><div class="section-head" style="margin:0"><div><div class="pill-row">${{niPill(niTitle(x.item_type),'neutral')}}</div><b style="display:block;margin-top:6px"><a href="${{targetHref(x)}}">${{niEsc(x.label)}}</a></b>${{x.note?`<div class="muted small" style="margin-top:5px">${{niEsc(x.note)}}</div>`:''}}</div><button class="ghost" type="button" onclick="removeItem('${{x.id}}')">Remove</button></div></article>`).join(''):'<div class="empty">No watched material.</div>';document.getElementById('watchAlerts').innerHTML=mine.length?mine.map(a=>`<article class="notice ${{['critical','high'].includes(a.severity)?'bad':a.severity==='medium'?'warn':''}}"><b>${{niEsc(a.title)}}</b><div class="small" style="margin-top:5px">${{niEsc(a.detail)}}</div><div class="muted small" style="margin-top:5px">${{niDate(a.occurred_at)}}</div><div class="toolbar" style="margin-top:8px"><a class="button secondary" href="${{niEsc(a.link)}}">Inspect</a><button class="ghost" type="button" onclick="ackAlert('${{encodeURIComponent(a.alert_key)}}')">Acknowledge</button></div></article>`).join(''):'<div class="empty">No unacknowledged changes for this watchlist.</div>'}}
async function load(){{try{{[watchlist,alerts]=await Promise.all([niApi(`/api/v1/watchlists/${{watchlistId}}`),niApi('/api/v1/workspace/alerts')]);render()}}catch(e){{document.getElementById('watchlistTitle').textContent='Watchlist unavailable';document.getElementById('watchItems').innerHTML=`<div class="error-box">${{niEsc(e.message)}}</div>`}}}}
async function removeItem(id){{try{{await niApi(`/api/v1/watchlists/${{watchlistId}}/items/${{id}}`,{{method:'DELETE'}});await load()}}catch(e){{niToast(e.message,'bad')}}}}
async function ackAlert(key){{try{{await niApi(`/api/v1/workspace/alerts/${{key}}/acknowledge`,{{method:'POST'}});await load()}}catch(e){{niToast(e.message,'bad')}}}}
async function deleteWatchlist(){{try{{await niApi(`/api/v1/watchlists/${{watchlistId}}`,{{method:'DELETE'}});location.href='/investigations'}}catch(e){{niToast(e.message,'bad')}}}}
document.getElementById('deleteWatchlistBtn').addEventListener('click',()=>document.getElementById('deleteWatchlistDialog').showModal());document.getElementById('confirmDeleteWatchlist').addEventListener('click',deleteWatchlist);load();
</script>"""
    extra_css = ".dialog-card{min-width:min(500px,calc(100vw - 36px));display:grid;gap:12px}dialog{border:1px solid var(--line);border-radius:16px;background:var(--surface);color:var(--text);box-shadow:var(--shadow);padding:20px}dialog::backdrop{background:rgba(10,18,35,.5)}"
    return render_app_page(title="Watchlist", body=body, active="investigations", role=role, scripts=scripts, extra_css=extra_css)
